55	/** A scenario the MHPCO refuses to process. */
56	export class ClaimOfficeError extends Error {}
57	
58	const PROCESSING_FEE = 5;
59	const FIRST_INSURANCE_SURCHARGE = 0.1;
60	const CURSE_SURCHARGE = 0.5;
61	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
62	const HIGH_ENCHANTMENT_THRESHOLD = 5;
63	const LOYALTY_DISCOUNT = 0.2;
64	const LOYALTY_THRESHOLD_YEARS = 2;
65	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
66	
67	const BASE_PREMIUMS: Record<string, number> = {
68	  sword: 100,
69	  amulet: 60,
70	  staff: 80,
71	  potion: 40,
72	  rune: 25,
73	  moonstone: 25,
74	};
75	
76	const INSURANCE_VALUES: Record<string, number> = {
77	  sword: 1000,
78	  amulet: 600,
79	  staff: 800,
80	  potion: 400,
81	  rune: 250,
82	  moonstone: 250,
83	};
84	
85	const DEDUCTIBLE = 100;
86	const CAP_MULTIPLIER = 2;
87	const PARTIAL_REIMBURSEMENT_THRESHOLD = 8;
88	const PARTIAL_REIMBURSEMENT_RATE = 0.5;
89	
90	const COMPONENT_TYPES = new Set(['rune', 'moonstone']);
91	const BLOCK_SIZE = 3;
92	const BLOCK_BASE_PREMIUM = 60;
93	
94	function isComponent(type: string): boolean {
95	  return COMPONENT_TYPES.has(type);
96	}
97	
98	/**
99	 * The base premium each item contributes, with the block discount for exactly
100	 * three alike components already spread across the block's members.
101	 */
102	function basePremiums(items: ItemInput[]): number[] {
103	  const componentCounts = new Map<string, number>();
104	  for (const item of items) {
105	    if (isComponent(item.type)) {
106	      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
107	    }
108	  }
109	
110	  return items.map((item) => {
111	    const listed = BASE_PREMIUMS[item.type];
112	    if (isComponent(item.type) && componentCounts.get(item.type) === BLOCK_SIZE) {
113	      return BLOCK_BASE_PREMIUM / BLOCK_SIZE;
114	    }
115	    return listed;
116	  });
117	}
118	
119	/**
120	 * Surcharges tied to a single item, expressed as a fraction of that item's own
121	 * base premium — not of the policy total.
122	 */
123	function itemSurchargeRate(item: ItemInput): number {
124	  let rate = FIRST_INSURANCE_SURCHARGE;
125	  if (item.cursed) rate += CURSE_SURCHARGE;
126	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
127	    rate += HIGH_ENCHANTMENT_SURCHARGE;
128	  }
129	  return rate;
130	}
131	
132	/**
133	 * Modifiers tied to the customer rather than any one item, expressed as a
134	 * fraction of the policy base premium.
135	 */
136	function policyModifierRate(customer: Customer, precedingContracts: number): number {
137	  let rate = 0;
138	  if (customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS) rate -= LOYALTY_DISCOUNT;
139	  if (precedingContracts > 0) rate -= FOLLOW_UP_CONTRACT_DISCOUNT;
140	  return rate;
141	}
142	
143	function quotePremium(
144	  items: ItemInput[],
145	  customer: Customer,
146	  precedingContracts: number,
147	): number {
148	  const bases = basePremiums(items);
149	  const policyBase = bases.reduce((sum, base) => sum + base, 0);
150	  const itemModifiers = bases.reduce(
151	    (sum, base, index) => sum + base * itemSurchargeRate(items[index]),
152	    0,
153	  );
154	  const policyModifiers = policyBase * policyModifierRate(customer, precedingContracts);
155	
156	  // Rounding favors the MHPCO: premiums round up.
157	  return Math.ceil(policyBase + itemModifiers + policyModifiers + PROCESSING_FEE);
158	}
159	
160	function assertInsurable(items: ItemInput[]): void {
161	  for (const item of items) {
162	    if (!(item.type in INSURANCE_VALUES)) {
163	      throw new ClaimOfficeError(`the MHPCO does not insure items of type ${item.type}`);
164	    }
165	  }
166	}
167	
168	function assertWellFormed(incident: Incident): void {
169	  for (const damage of incident.damages) {
170	    if (damage.amount < 0) {
171	      throw new ClaimOfficeError(
172	        `damage amount ${damage.amount} for ${damage.itemType} is negative`,
173	      );
174	    }
175	  }
176	}
177	
178	/** A policy created by a quote step, tracking how much of its cap is left. */
179	interface Policy {
180	  items: ItemInput[];
181	  remainingCap: number;
182	}
183	
184	function openPolicy(items: ItemInput[]): Policy {
185	  const insuranceSum = items.reduce(
186	    (sum, item) => sum + INSURANCE_VALUES[item.type],
187	    0,
188	  );
189	  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
190	}
191	
192	function reimbursableAmount(damage: Damage, item: ItemInput): number {
193	  if ((item.enchantment ?? 0) >= PARTIAL_REIMBURSEMENT_THRESHOLD) {
194	    return damage.amount * PARTIAL_REIMBURSEMENT_RATE;
195	  }
196	  return damage.amount;
197	}
198	
199	/**
200	 * Pairs each damage with a distinct insured item, so a policy covering one
201	 * sword cannot absorb two sword damages.
202	 */
203	function matchDamagesToItems(policy: Policy, damages: Damage[]): ItemInput[] {
204	  const unclaimed = [...policy.items];
205	
206	  return damages.map((damage) => {
207	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
208	    if (index === -1) {
209	      throw new ClaimOfficeError(
210	        `the policy does not cover a ${damage.itemType} for this damage entry`,
211	      );
212	    }
213	    return unclaimed.splice(index, 1)[0];
214	  });
215	}
216	
217	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
218	  assertWellFormed(incident);
219	  const damagedItems = matchDamagesToItems(policy, incident.damages);
220	  const desired = incident.damages.reduce(
221	    (sum, damage, index) =>
222	      sum + Math.max(0, reimbursableAmount(damage, damagedItems[index]) - DEDUCTIBLE),
223	    0,
224	  );
225	  // Rounding favors the MHPCO: payouts round down.
226	  const payout = Math.floor(Math.min(desired, policy.remainingCap));
227	  policy.remainingCap -= payout;
228	
229	  return { payout, remainingCap: policy.remainingCap };
230	}
231	
232	export function runScenario(scenario: Scenario): ScenarioResult {
233	  const results: StepResult[] = [];
234	  const policies = new Map<number, Policy>();
235	  let contractsSoFar = 0;
236	
237	  scenario.steps.forEach((step, index) => {
238	    if (step.op === 'quote') {
239	      assertInsurable(step.items);
240	      results.push({
241	        premium: quotePremium(step.items, scenario.customer, contractsSoFar),
242	      });
243	      policies.set(index, openPolicy(step.items));
244	      contractsSoFar += 1;
245	      return;
246	    }
247	
248	    const policy = policies.get(step.policy);
249	    if (!policy) {
250	      throw new ClaimOfficeError(`step ${step.policy} did not create a policy`);
251	    }
252	    results.push(settleClaim(policy, step.incident));
253	  });
254	
255	  return { results };
256	}
