1	#!/usr/bin/env node
2	import { ClaimOfficeError, runScenario, type Scenario } from './scenario.js';
3	
4	async function readStdin(): Promise<string> {
5	  const chunks: Buffer[] = [];
6	  for await (const chunk of process.stdin) {
7	    chunks.push(Buffer.from(chunk));
8	  }
9	  return Buffer.concat(chunks).toString('utf8');
10	}
11	
12	async function main(): Promise<void> {
13	  const input = await readStdin();
14	
15	  let scenario: Scenario;
16	  try {
17	    scenario = JSON.parse(input) as Scenario;
18	  } catch {
19	    throw new ClaimOfficeError('stdin does not contain a valid JSON scenario');
20	  }
21	
22	  const result = runScenario(scenario);
23	  process.stdout.write(JSON.stringify(result));
24	}
25	
26	main().catch((error: unknown) => {
27	  const message = error instanceof Error ? error.message : String(error);
28	  process.stderr.write(`claim-office: ${message}\n`);
29	  process.exitCode = 1;
30	});
