5	const CLI = fileURLToPath(new URL('./cli.ts', import.meta.url));
6	
7	interface CliOutcome {
8	  code: number;
9	  stdout: string;
10	  stderr: string;
11	}
12	
13	function runCli(input: string): Promise<CliOutcome> {
14	  return new Promise((resolve) => {
15	    const child = execFile('npx', ['tsx', CLI], (error, stdout, stderr) => {
16	      resolve({ code: error ? ((error as { code?: number }).code ?? 1) : 0, stdout, stderr });
17	    });
18	    child.stdin!.end(input);
19	  });
20	}
